const BID_STEP_RULE = 10;          // (the auction's step, for the rules' text; the engine has its own)
// whose heroes a theme plays with: its own (or, with heroes: KEY, another theme's)
const heroSet = theme => { const th = THEMES[theme] || THEMES.mamuli; return th.heroes || th.key; };
const heroKeys = theme => Object.keys(HEROES).filter(h => HEROES[h].t === heroSet(theme));
const themeOf = st => THEMES[st && st.theme] || THEMES.mamuli;
let THEME = THEMES.mamuli;
const W = Object.assign({}, THEME.w);       // the words of the theme on screen
const LEVEL_NAMES = THEME.levels.slice();

// a theme's names and words go where the rest of the game reads them (the rules do not change)
function useTheme(key) {
  const th = THEMES[key] || THEMES.mamuli;
  if (th === THEME && BOARD[1].n === th.names[1].n) return false;
  THEME = th;
  BOARD.forEach((t, i) => { t.n = th.names[i].n; if (th.names[i].s) t.s = th.names[i].s; else delete t.s; });
  GROUPS.forEach((g, i) => { g.n = th.groups[i].n; g.c = th.groups[i].c; });
  for (const k of Object.keys(W)) delete W[k];
  Object.assign(W, th.w);
  LEVEL_NAMES.splice(0, LEVEL_NAMES.length, ...th.levels);
  if (typeof LEVELS !== 'undefined') th.levels.forEach((n, i) => { if (LEVELS[i]) LEVELS[i].n = n; });
  return true;
}

if (typeof module !== 'undefined') module.exports = { THEMES, QUIZ_TIME, QUIZ_WIN, QUIZ_SHARE, heroSet, heroKeys, themeOf, useTheme };
